      unless _s_v7.is_a?(::Integer) && _s_v7 >= 0 && _s_v7 <= 7
        ::Example._s_validate_int(_s_v7, "#{path}.tail", 0, 7)
      end
      nil
    end

    def _s_zero
      self.lead = 0
      self.items = [] #: ::Array[Eleven]
      self.tail = 0
      nil
    end

  end

  class Sole
    attr_accessor :only

    def initialize
      @only = 0
    end

    def _s_copy_from(other)
      self.only = other.only
      self
    end

    def to_h = { only: @only }

    def ==(other)
      return false unless other.instance_of?(Sole)
      _s_o = other #: Sole
      self.only == _s_o.only
    end

    def inspect
      "Sole(only=#{self.only.inspect})"
    end

    def self.read_bits(data, bit_offset: 0)
      stream, rem = ::Example._s_open_read_stream(data, bit_offset)
      value = Sole.new
      raise Refused.new(stream.refusal || "rejected") unless value._s_read(stream)
      [value, stream.bits_processed - rem]
    end

    def self.read(data)
      pair = Sole.read_bits(data)
      pair[0]
    end

    def write
      _s_validate("Sole")
      stream = WriteStream.new(8)
      begin
        _s_write(stream)
      rescue Serialize::WriteMisuse => _e
        raise InvalidValue.new("Sole", _e.message)
      end
      stream.flush
      stream.data
    end

    def _s_read(stream)
      _s_ri = Serialize::Ref.new(0)
      return false unless stream.serialize_bits(_s_ri, 13)
      self.only = _s_ri.value
      true
    end

    def _s_write(stream)
      _s_ri = Serialize::Ref.new(0)
      _s_ri.value = self.only
      stream.serialize_bits(_s_ri, 13)
      nil
    end

    def _s_validate(path)
      _s_v1 = self.only #: untyped
      unless _s_v1.is_a?(::Integer) && _s_v1 >= 0 && _s_v1 <= 8191
        ::Example._s_validate_int(_s_v1, "#{path}.only", 0, 8191)
      end
      nil
    end

    def _s_zero
      self.only = 0
      nil
    end

  end
